  //   title: "FAS – Free Alongside Ship (Named Port of Shipment)",
  //   author: "Anup Parikh",
  //   updated: "2026-07-12",
  //   readingTime: 10,
  //   summary:
  //     "FAS – Free Alongside Ship requires the seller to deliver goods alongside the vessel nominated by the buyer at the named port of shipment. The buyer bears the risk from that point onward.",
  //   sections: [
  //     {
  //       heading: "Introduction",
  //       blocks: [
  //         {
  //           type: "paragraph",
  //           text: "FAS – Free Alongside Ship (named port of shipment)",
  //         },
  //         {
  //           type: "paragraph",
  //           text: "FAS – Free Alongside Ship (named port of shipment, dry/liquid bulk terminal)",
  //         },
  //         {
  //           type: "paragraph",
  //           text: "Since the goods transported require specialized facilities for transport and warehousing, the dry / liquid bulk terminal area becomes the designated spot within the named port of shipment.",
  //         },
  //         {
  //           type: "paragraph",
  //           text: "It is possible that the pier number may be unavailable at the time of entering into the contract. Once received, the buyer must immediately communicate those details to the seller.",
  //         },
  //         {
  //           type: "paragraph",
  //           text: "Incoterm FAS is exclusive to sea and inland waterway transport.",
  //         },
  //       ],
  //     },

  //     {
  //       heading: "Delivery and Risk Transfer",
  //       blocks: [
  //         {
  //           type: "paragraph",
  //           text: "Delivery occurs when the goods are placed alongside the ship nominated by the buyer at the named port of shipment.",
  //         },
  //         {
  //           type: "paragraph",
  //           text: "Where the seller transports goods by quay or barge for loading onto the vessel, delivery is also considered compliant because the quay or barge is regarded as being alongside the ship.",
  //         },
  //         {
  //           type: "paragraph",
  //           text: "Additionally, delivery is compliant when goods are procured already ready for shipment. This is referred to as 'or procuring the goods so delivered.'",
  //         },
  //         {
  //           type: "paragraph",
  //           text: "This provision facilitates 'string sales', where goods change ownership multiple times before reaching the ultimate buyer.",
  //         },
  //       ],
  //     },

  //     {
  //       heading: "Bulk Cargo and Specialized Terminals",
  //       blocks: [
  //         {
  //           type: "paragraph",
  //           text: "FAS is generally used for unpackaged bulk commodities such as grain, timber, coal, minerals and ores.",
