  //           text: "Where the vessel cannot berth because of insufficient draft and barges are required, the seller bears the cost of transporting the goods by barge until they are placed alongside the ship.",
  //         },
  //         {
  //           type: "paragraph",
  //           text: "Delivery may also take place through specialized dry or liquid bulk terminals designed for handling bulk commodities.",
  //         },
  //         {
  //           type: "paragraph",
  //           text: "For containerized cargo, FCA should be used instead of FAS because containers are delivered to container terminals rather than alongside a vessel.",
