      {
        heading:
          "(Part 14) Relationship between Freight, additional costs and Incoterms when read along with ISBP rules E26 & E27 and Article 26(c) of UCP 600.",
        blocks: [
          {
            type: "paragraph",
            text: "Article 26(C) of UCP 600 approves a reference, by stamp or otherwise to charges additional to the freight. This article aims to highlight the additional costs involved beyond the cost of transportation from the port of loading to the port of discharge."
          },
          {
            type: "paragraph",
            text: "Rule E(26) and E(27) of ISBP 821 aim to provide clarity as to how additional costs are recorded in different documents stipulated in the credit as well as the credit."
          },
          {
            type: "paragraph",
            text: "Rule E (26) of ISBP 821 states that the bill of lading must mirror the functionality with regards to payment of freight when compared with the data in the credit. This rule emphasises that when it comes to payment of freight – the bill of lading need not be identical but must convey consistent meaning along all relevant documents stated in the credit."
          },
          {
            type: "paragraph",
            text: "This rule highlights the difference in terminology used by bankers and shipping companies. This difference is explained through the example where freight payable at destination and freight collect convey the same meaning."
          },
          {
            type: "paragraph",
            text: "Rule E (26) of ISBP 821 is consistent with the Rule A (6)(b) of ISBP 821 which explains that data shown on a copy of a transport document when read in context with the credit need not be identical but must not conflict with, data in that document or any other stipulated document in the credit. Article 14(e) of UCP 600 reiterates the position and maintains that the description may be in general terms not conflicting with their description in the credit."
          },
          {
            type: "paragraph",
            text: "Article 26(c) of UCP 600 when read along with Rule E (27)(a) of ISBP 821 states that when credit prohibits any additional charges in addition to freight, then Bill of Lading must comply. When bill of lading records any additional charges over and above freight, then bill of lading will be considered discrepant at the time of presentation to the bank."
          },
          {
            type: "paragraph",
            text: "However, an exception is made out to the position held above in Rule E (27)(b) of ISBP 821. This rule states that when an indication to cost with respect to loading and unloading of goods in addition to freight, such costs are acceptable."
          },
          {
            type: "paragraph",
            text: "Rule E (27)(b) of ISBP 821 expands the understanding of additional costs associated with loading and unloading of goods. Trade terms such as Free In (FI), Free Out (FO), Free In and Out (FIO) and Free In and Out stowed (FIOS). The rule provides clarity about the trade terms indicating the list is not exhaustive – however the rule is clear that additional costs related to loading and unloading are acceptable and in compliance with Article 26(c) of UCP 600 and Rule E(27)(a) of ISBP 821."
          },
          {
            type: "paragraph",
            text: "Understanding the trade terms like FI, FO, FIO and FIOS helps parties to negotiate and record liability. The purpose of recording trade terms in credit is to clarity upfront about the breakup of charges payable by the parties involved. For a document checker, these terms are for the reference only and do not qualify as additional costs to freight."
          },
          {
            type: "paragraph",
            text: "Rule 27(C) of ISBP 821 deals with costs that are beyond freight and not related to loading and unloading of goods. This rule covers charges related to demurrage costs, detention costs and other cost / penalties. These charges are excluded from being considered as freight and any mention of such charges in the Bill of Lading is acceptable and that the transport document is compliant subject to Article 26(c) of UCP 600 and Rule 26 and 27 of ISBP 821 and overall terms of the credit."
          }
        ]
      },

      {
        heading:
          "(Part 15) Rules regarding consignee party, order party, shipper and endorsement and notify party with reference to UCP 600, ISBP821 and SWIFT MT 700",
        blocks: [
          {
            type: "paragraph",
            text: "To understand Rule E12 of ISBP it is important to have a brief understanding of shipping terms used."
          },
          {
            type: "paragraph",
            text: "“Consigned to a named party” – This shipping term refers to the party for whom the goods are intended for delivery. This party is listed as consignee on the bill of lading."
          },
          {
            type: "paragraph",
            text: "“Straight Bill of Lading” is a form of bill of lading which is non-negotiable, implying the name of the consignee cannot be changed. The legal title and ownership of the cargo with Straight Bill of Lading always remains with the consignee."
          },
          {
            type: "paragraph",
            text: "“To order” implies that the legal title of the cargo is transferable to a third party through endorsements. The shipper retains the title and determines who collects the goods at the port of discharge. The party who collects the goods at the port of discharge does this by surrendering atleast one original copy to the carrier."
          },
          {
            type: "paragraph",
            text: "Rule E (12) of ISBP 821 covers the situation where goods are consigned to a named entity. When the bill of lading is consigned to a named party then it must not contain the expressions “to order” or “to order of preceding the named entity” either in typed or pre-printed form. This rule makes the distinction between “Straight Bill of Lading” and “Order Bill of Lading”."
          },
          {
            type: "paragraph",
            text: "Rule E (13)(a) of ISBP 821 deals with endorsement where Bill of Lading is issued “to order” or “to order of the shipper”. In such circumstances the bill of Lading must be endorsed by the shipper. Endorsement made by a named entity other than the shipper must be made for on or behalf of the shipper."
          },
          {
            type: "paragraph",
            text: "Rule E (13)(b) of ISBP 821 states that either the Bill of Lading is an “Order Bill of Lading” or “Straight Bill of Lading”."
          },
          {
            type: "paragraph",
            text: "To understand Rule E14 of ISBP it is important to have a brief understanding of shipping term used."
          },
          {
            type: "paragraph",
            text: "Notify Party as the term suggests is the party who is notified when the cargo arrives at the port of unloading. Notify Party details will contain the name, address and contact details about the arrival of the cargo."
          },
          {
            type: "paragraph",
            text: "As the name suggests notify party is only informed about the arrival of the cargo at the port of unloading. All the other formalities and clearance is the responsibility of the notify party."
          },
          {
            type: "paragraph",
            text: "Rule 14(a) of ISBP 821 states that when a credit stipulates multiple notify parties, then a bill of lading may also indicate the details of one or more additional notify parties."
          },
          {
            type: "paragraph",
            text: "The details about notify party will be recorded in one of the following fields of MT 700 -"
          },
          {
            type: "list",
            items: [
              "Field 47A: Additional Conditions",
              "Field 72Z: Sender to Receiver Information."
            ]
          },
          {
            type: "paragraph",
            text: "Rule 14(b)(i) of ISBP 821 states that it is not always mandatory to record notify party in the credit, it is sufficient that notify party is recorded in bill of lading or in any manner. The rationale behind this is since Bill of lading is a shipping document, document checker need not be involved verifying this minor detail."
          },
          {
            type: "paragraph",
            text: "Exception to the above rule is provided in Rule (14)(b)(ii) of ISBP 821. The rule states that when the credit is silent on the details of notify party and the applicant’s name appears as notify party on bill of lading then the address and contact details need not be mentioned separately as all the details are mentioned in different field of the same Bill of Lading."
          },
          {
            type: "paragraph",
            text: "Rule 14(b)(ii) and 16 of ISBP 821 deals with the consistency of the address of the applicant across the transport document i.e., the Bill of Lading and the Credit. Article 14(j) of UCP 600 reiterates the position held and affirms that the addresses recorded need not be in conflict."
          },
          {
            type: "paragraph",
            text: "Rule 15 of ISBP 821 deals with the situation where Field 46A of MT 700 mandates Bill of Lading be consigned to or to the order of issuing bank or applicant or notify “applicant” or “issuing bank” then a Bill of Lading is compliant when the name of the issuing bank or applicant as applicable."
          },
          {
            type: "paragraph",
            text: "Address and contact details of the applicant or issuing bank need not be stated."
          }
        ]
      }
