            text: "In Field 46A of MT700 which deals with the documents required for presentation by the applicant must record the condition – “Blank Back Non-Negotiable Sea Waybill / Short Form Non-Negotiable Sea Waybill is acceptable”. In the absence of such a stipulation, any submission of Blank Back Non-Negotiable Sea Waybill / Short Form Non-Negotiable Sea Waybill will be deemed as discrepancy at the time of presentation of documents under Article 14 of UCP 600."
