              "When Letter of Credit prohibits transhipment, transhipment refers to the voyage from port of loading to the port of discharge as stated in the credit. Article 21(d) of UCP 600 states that clauses in the Non-Negotiable Sea Waybill stating that the carrier reserves the right to tranship will be disregarded. This implies that how the carrier moves the goods during voyage is the sole prerogative of the carrier."
