      {
        heading: "Part 15: Relationship between Freight, additional costs and Incoterms when read along with ISBP rules F(24) & F(25) and Article 26(c) of UCP 600",
        blocks: [
          {
            type: "paragraph",
            text: "Rule F(24) of ISBP 821 states that when the payment of freight is indicated through the Non-Negotiable Sea Waybill, then the data needs to be consistent with other document stipulated in the credit along with the conditions laid down in the credit. This rule through example attempts to bridge the gap between usage of Incoterm and logistics carriage term. The purpose is acknowledge that the transport document can incorporate logistics terms rather than Incoterm and this usage is perfectly acceptable at the time of presentation."
          },
          {
            type: "paragraph",
            text: "Article 26(C) of UCP 600 approves a reference, by stamp or otherwise to charges additional to the freight. This article aims to highlight the additional costs involved beyond the cost of transportation from the port of loading to the port of discharge."
          },
          {
            type: "paragraph",
            text: "Rule F(24) of ISBP 821 is consistent with the Rule A (6)(b) of ISBP 821 which explains that data shown on a copy of a transport document when read in context with the credit need not be identical but must not conflict with, data in that document or any other stipulated document in the credit. Article 14(e) of UCP 600 reiterates the position and maintains that the description may be in general terms not conflicting with their description in the credit."
          },
          {
            type: "paragraph",
            text: "Article 26(c) of UCP 600 when read along with Rule F(25)(a) of ISBP 821 states that when credit prohibits any additional charges in addition to freight, then Bill of Lading must comply. When bill of lading records any additional charges over and above freight, then bill of lading will be considered discrepant at the time of presentation to the bank."
          },
          {
            type: "paragraph",
            text: "However, an exception is made out to the position held above in Rule F(25)(b) of ISBP 821. This rule states that when an indication to cost with respect to loading and unloading of goods in addition to freight, such costs are acceptable."
          },
          {
            type: "paragraph",
            text: "Rule F(25)(b) of ISBP 821 expands the understanding of additional costs associated with loading and unloading of goods. Trade terms such as Free In (FI), Free Out (FO), Free In and Out (FIO) and Free In and Out stowed (FIOS). The rule provides clarity about the trade terms indicating the list is not exhaustive – however the rule is clear that additional costs related to loading and unloading are acceptable and in compliance with Article 26(c) of UCP 600 and Rule F(25)(a) of ISBP 821."
          },
          {
            type: "paragraph",
            text: "Understanding the trade terms like FI, FO, FIO and FIOS helps parties to negotiate and record liability. The purpose of recording trade terms in credit is to clarity upfront about the breakup of charges payable by the parties involved. For a document checker, these terms are for the reference only and do not qualify as additional costs to freight."
          },
          {
            type: "paragraph",
            text: "Rule F(25)(c) of ISBP 821 deals with costs that are beyond freight and not related to loading and unloading of goods. This rule covers charges related to demurrage costs, detention costs and other cost / penalties. These charges are excluded from being considered as freight and any mention of such charges in the Bill of Lading is acceptable and that the transport document is compliant subject to Article 26(c) of UCP 600 and Rule F(24) and F(25) of ISBP 821 and overall terms of the credit."
          }
        ]
      }
