            type: "paragraph",
            text: "When Field 47A of MT 700 requires the document checker to examine the carriage contract, the document checker will not comply with these instructions. Article 23(a)(vi) of UCP 600 supports this position. Additionally, this position is supported by Article 4(a), 4(b) and 5 of UCP 600 which highlight the position that credit is a separate transaction from the sale or other contract on which it may be based. Furthermore, banks deal with documents and not with goods, services or performance to which the documents may relate."
