            text: "In instances where transhipment is permitted through Field 43T of MT 700 even then the shipper must submit only Airway Bill that covers the entire journey by evidencing flights and the airport where transhipment will take place. The rationale behind such a position is multiple Airway Bill indicates multiple shipment leading to evidencing of partial shipment."
