            type: "paragraph",
            text: "Field 43T permits one of the following codes: Allowed, Conditional and Not Allowed. While Allowed and Not Allowed codes are straightforward in the meaning, usage of Conditional code in the field implies that Transhipment is permitted subject to conditions specified in other fields of the credit. This implies Swift Standards permits Transhipment based on (documentary / routing) contingencies recorded in Field 47A of MT 700. The contingencies need to be documentary verifiable / compliant at the time of presentation. In the absence of documentary compliance, transhipment will be considered not allowed."
