            type: "paragraph",
            text: "The objective of Article 23 of UCP 600 and Rule H of ISBP 821 is to confirm that the goods have been shipped on board and when the goods are in unit load devices the carrier reserves the right for transhipment even when letter of credit prohibits transhipment. Unit Load device is a logistics term used in Aviation Cargo. Therefore, when transhipment falls under the purview of Article 23(c)(i) and Article 23(c)(ii) of UCP 600 is prerogative of the carrier, there is no need for a second on-board notation indicating that the goods have been shipped on second aircraft. This position applies even when transhipment is permitted."
