            text: "When there is an additional mode of transport included in the flights as part of transhipment then Article 19 of UCP 600 and Rule D of ISBP 821 is applied at the time of examination of documents during presentation. Hence, inclusion of such additional mode of transport would constitute discrepancy at the time of examination of documents at the time of presentation when the credit mandates submission of air transport document."
