export const findArticle = (slug) => articles.find((a) => a.slug === slug);

export const getAllArticles = () => articles;

export const getPublishedArticles = () =>
  articles.filter((article) => article.published !== false);

export const findPublishedArticle = (slug) =>
  getPublishedArticles().find((article) => article.slug === slug) || null;
